Salve como `vazamento.js` e rode com `node vazamento.js`. O script simula 500 requisições de duas formas: uma que registra um listener no barramento e nunca o remove (guardando o payload num `Map` de módulo) e outra que faz a desmontagem com `off()`.

```
const { EventEmitter } = require('node:events')

const barramento = new EventEmitter()
barramento.setMaxListeners(0)
const cache = new Map()

// handler que "esquece" de remover o listener e guarda o payload num Map global
function requisicaoComVazamento(id) {
  const payload = Buffer.alloc(1024, id % 256)
  const aoAtualizar = () => cache.set(id, payload)
  barramento.on('atualizou', aoAtualizar)
  barramento.emit('atualizou')
}

// mesma coisa, com desmontagem
function requisicaoLimpa(id) {
  const payload = Buffer.alloc(1024, id % 256)
  const aoAtualizar = () => payload.length
  barramento.on('atualizou', aoAtualizar)
  barramento.emit('atualizou')
  barramento.off('atualizou', aoAtualizar)
}

for (let i = 0; i < 500; i++) requisicaoComVazamento(i)
console.log('listeners apos 500 requisicoes:', barramento.listenerCount('atualizou'))
console.log('entradas retidas no Map:', cache.size)
console.log('bytes retidos pelo Map:', cache.size * 1024)

barramento.removeAllListeners('atualizou')
cache.clear()

for (let i = 0; i < 500; i++) requisicaoLimpa(i)
console.log('listeners com off():', barramento.listenerCount('atualizou'))
console.log('entradas retidas no Map:', cache.size)
```

