Salve como `nmais1.js` e rode com `node nmais1.js`. O "banco" é falso de propósito: ele só conta quantas consultas foram feitas e cobra 2 ms de ida e volta em cada uma. Duas implementações do mesmo endpoint produzem exatamente o mesmo JSON.

```
// "banco" falso que so conta consultas e cobra 2 ms de ida e volta
let consultas = 0
const espera = (ms) => new Promise((r) => setTimeout(r, ms))
const PEDIDOS = Array.from({ length: 100 }, (_, i) => ({ id: i + 1, clienteId: (i % 20) + 1 }))
const CLIENTES = Array.from({ length: 20 }, (_, i) => ({ id: i + 1, nome: 'cliente-' + (i + 1) }))

async function query(fn) {
  consultas += 1
  await espera(2)
  return fn()
}

async function listarNMais1() {
  const pedidos = await query(() => PEDIDOS)
  const saida = []
  for (const p of pedidos) {
    const c = await query(() => CLIENTES.find((x) => x.id === p.clienteId))
    saida.push({ ...p, cliente: c.nome })
  }
  return saida
}

async function listarEmLote() {
  const pedidos = await query(() => PEDIDOS)
  const ids = [...new Set(pedidos.map((p) => p.clienteId))]
  const clientes = await query(() => CLIENTES.filter((c) => ids.includes(c.id)))
  const porId = new Map(clientes.map((c) => [c.id, c]))
  return pedidos.map((p) => ({ ...p, cliente: porId.get(p.clienteId).nome }))
}

async function main() {
  consultas = 0
  const a = await listarNMais1()
  const consultasA = consultas
  consultas = 0
  const b = await listarEmLote()
  const consultasB = consultas
  console.log('n+1 consultas:', consultasA)
  console.log('lote consultas:', consultasB)
  console.log('mesmo resultado:', JSON.stringify(a) === JSON.stringify(b))
  console.log('idas ao banco evitadas:', consultasA - consultasB)
}
main()
```

Antes de rodar, calcule no papel quanto tempo cada versão gasta só de ida e volta ao banco (consultas × 2 ms) e qual seria o ganho com 1000 pedidos em vez de 100.

